using System;using System.Linq;using System.IO;using System.Text;using System.Collections.Generic;using System.Drawing;using Frociart;
internal static class InlineCycleTests {
 static int checks;
 static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static string Enc(Diagram d){return Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d));}
 static string Runtime(Diagram d){var r=new Interpreter(d);for(int i=0;i<5000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Original graph completes: "+r.Error);return r.OutputText.Replace("\r\n","\n");}
 static string Structural(Diagram graph){return String.Join("|",graph.Nodes.Select(n=>n.Id+":"+n.Kind+":"+n.Text+":"+n.X+":"+n.Y))+String.Join("|",graph.Edges.Select(e=>e.Id+":"+e.From+":"+e.To+":"+e.Branch));}
 static void Validate(Diagram graph,FlowCycleFold fold){var p=fold.Current;if(p==null){Check(!fold.Cycles.Any(c=>graph.Nodes.First(n=>n.Id==c.Check).FoldedCycle),"Null projection has no folded cycles");return;}
  var seen=new HashSet<string>(p.Scene.Nodes.Select(n=>n.Id));Check(seen.Count==p.Scene.Nodes.Count,"Scene IDs unique");foreach(var n in graph.Nodes)Check(seen.Contains(p.Owner(n.Id)),"Every original node represented");
  foreach(var e in p.Scene.Edges){var original=graph.Edges.Single(n=>n.Id==e.Id);Check(e.From==p.Owner(original.From)&&e.To==p.Owner(original.To)&&seen.Contains(e.From)&&seen.Contains(e.To),"Actual edge identity maps to visible endpoints");}
  foreach(var c in p.Cards.Values){Check(new HashSet<string>(p.Selection(new[]{c.Entry})).SetEquals(c.Members),"Capsule selects complete executable group");foreach(string id in c.Members)Check(p.ContainsActive(c.Entry,id),"Every runtime step maps to its capsule");var entry=graph.Nodes.First(n=>n.Id==c.Entry);var card=p.Visual(c.Entry);Check(Math.Abs(entry.X+FlowSizing.Size(entry).Width/2-card.X-FlowSizing.Size(card).Width/2)<.01f,"Header preserves center X");var edge=p.Scene.Edges.Single(e=>e.From==c.Entry);var target=p.Visual(edge.To);Check(target.Y+.1f>=card.Y+FlowSizing.Size(card).Height,"Downstream remains below capsule: card="+card.Text+" y="+card.Y+" height="+FlowSizing.Size(card).Height+" target="+target.Text+" targetY="+target.Y+" originalY="+p.SourceNodes[target.Id].Y);}
 }
 static int Main(string[] args){try{string root=args[0];foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"))){var row=line.Split('\t');string code=Encoding.UTF8.GetString(Convert.FromBase64String(row[1])),expected=Encoding.UTF8.GetString(Convert.FromBase64String(row[2]));var document=FlowPseudocode.Decode(code);string before=Enc(document);Check(Runtime(document)==expected,"Initial result "+row[0]);
  foreach(var graph in FunctionEditing.Graphs(document)){string structural=Structural(graph);var fold=new FlowCycleFold(graph);Check(fold.Current==null,"Default expanded");fold.All(true);Validate(graph,fold);Check(Structural(graph)==structural,"Fold preserves positions and executable graph");Check(Runtime(document)==expected,"Fold preserves interpreter "+row[0]);var clone=DiagramIO.Clone(document);Check(FunctionEditing.Graphs(clone).Sum(g=>g.Nodes.Count(n=>n.FoldedCycle))==FunctionEditing.Graphs(document).Sum(g=>g.Nodes.Count(n=>n.FoldedCycle)),"Persistent flags survive native clone");
   if(fold.Current!=null){var current=fold.Current;var c=current.Cards.Values.First();float x=current.Visual(c.Entry).X,y=current.Visual(c.Entry).Y;int builds=fold.Rebuilds;for(int i=0;i<1000;i++)current.Sync();Check(fold.Rebuilds==builds,"Pointer geometry sync never recognizes cycles again");foreach(var n in graph.Nodes.Where(n=>c.Members.Contains(n.Id))){n.X+=48;n.Y+=24;}fold.Update();Check(Object.ReferenceEquals(current,fold.Current)&&fold.Rebuilds==builds,"Move reuses current scene");Check(Math.Abs(current.Visual(c.Entry).X-x-48)<.01f&&Math.Abs(current.Visual(c.Entry).Y-y-24)<.01f,"Whole-group move remains at released position");foreach(var n in graph.Nodes.Where(n=>c.Members.Contains(n.Id))){n.X-=48;n.Y-=24;}fold.Update();Check(Structural(graph)==structural,"Restored move preserves graph");}
   var outer=fold.Cycles.FirstOrDefault(c=>fold.Cycles.Any(n=>n.Members.IsProperSubsetOf(c.Members)));if(outer!=null){var inner=fold.Cycles.First(c=>c.Members.IsProperSubsetOf(outer.Members));Check(fold.Current.Cards.ContainsKey(outer.Entry)&&!fold.Current.Cards.ContainsKey(inner.Entry),"Outer fold owns nested cycle");fold.Set(outer.Check,false);Check(fold.Current!=null&&fold.Current.Cards.ContainsKey(inner.Entry),"Unfold keeps inner presentation choice");fold.Reveal(inner.BodyEntry);Check(!graph.Nodes.First(n=>n.Id==inner.Check).FoldedCycle,"Reveal original node expands enclosing folds");}
   fold.All(false);Check(fold.Current==null&&Structural(graph)==structural,"Expand restores original geometry");
  }
  Check(Enc(document)==before,"Full fold/unfold leaves original bytes unchanged");var load=FlowPseudocode.Decode(code);foreach(var graph in FunctionEditing.Graphs(load))new FlowCycleFold(graph).All(true);string file=Path.Combine(root,"pc-"+row[0]+".frociart");DiagramIO.Save(file,load);Check(Runtime(DiagramIO.Load(file))==expected,"Save/reopen preserves algorithm");Console.WriteLine("PASS "+row[0]);
 }
 Console.WriteLine("INLINE_CYCLE_PC_CORE PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
